    "scriptureAnchor": {
      "reference": "Galatians 2:20",
      "text": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.",
      "book": "Galatians",
      "chapter": 2,
      "verse": 20
    },
    "stanzas": [
      {
        "number": 1,
        "text": "We come, our gracious Father,\nWith many hearts as one,\nAnd here we only gather\nIn memory of Thy Son:\nWe prize each happy token\nOf peace with Thee, our God;\nThe bread, His body broken;\nThe wine, His precious blood."
      },
      {
        "number": 2,
        "text": "Whilst breaking bread we ponder,\nLord Jesus, on Thy love,\nAnd see, with silent wonder.\nWhat drew Thee from above.\nComplete in Thy completeness,\nThe Church, Thy favoured Bride,\nPossesses all the Sweetness\nThy perfect love supplied."
      }
    ],
